1617	/// Create a new pool that contains the names of all the types defined
1618	/// in the document and the names of all their fields
1619	fn atom_pool(document: &s::Document) -> AtomPool {
1620	    let mut pool = AtomPool::new();
1621	
1622	    pool.intern(&ID);
1623	    // Name and attributes of PoI entity type
1624	    pool.intern(POI_OBJECT);
1625	    pool.intern(POI_DIGEST);
1626	    pool.intern(POI_BLOCK_TIME);
1627	
1628	    pool.intern(VID_FIELD);
1629	
1630	    for definition in &document.definitions {
1631	        match definition {
1632	            s::Definition::TypeDefinition(typedef) => match typedef {
1633	                s::TypeDefinition::Object(t) => {
1634	                    static NO_VALUE: Vec<Value> = Vec::new();
1635	
1636	                    pool.intern(&t.name);
1637	
1638	                    // For timeseries, also intern the names of the
1639	                    // additional types we generate.
1640	                    let intervals = t
1641	                        .find_directive(kw::AGGREGATION)
1642	                        .and_then(|dir| dir.argument(kw::INTERVALS))
1643	                        .and_then(Value::as_list)
1644	                        .unwrap_or(&NO_VALUE);
1645	                    for interval in intervals {
1646	                        if let Some(interval) = interval.as_str() {
1647	                            pool.intern(&format!("{}_{}", t.name, interval));
1648	                        }
1649	                    }
1650	                    for field in &t.fields {
1651	                        pool.intern(&field.name);
1652	                    }
1653	                }
1654	                s::TypeDefinition::Enum(t) => {
1655	                    pool.intern(&t.name);
1656	                }
1657	                s::TypeDefinition::Interface(t) => {
1658	                    pool.intern(&t.name);
1659	                    for field in &t.fields {
1660	                        pool.intern(&field.name);
1661	                    }
1662	                }
1663	                s::TypeDefinition::InputObject(input_object) => {
1664	                    pool.intern(&input_object.name);
1665	                    for field in &input_object.fields {
1666	                        pool.intern(&field.name);
1667	                    }
1668	                }
1669	                s::TypeDefinition::Scalar(scalar_type) => {
1670	                    pool.intern(&scalar_type.name);
1671	                }
1672	                s::TypeDefinition::Union(union_type) => {
1673	                    pool.intern(&union_type.name);
1674	                    for typ in &union_type.types {
1675	                        pool.intern(typ);
1676	                    }
1677	                }
1678	            },
1679	            s::Definition::SchemaDefinition(_)
1680	            | s::Definition::TypeExtension(_)
1681	            | s::Definition::DirectiveDefinition(_) => { /* ignore, these only happen for introspection schemas */
1682	            }
1683	        }
1684	    }
1685	
1686	    for object_type in document.get_object_type_definitions() {
1687	        for defn in InputSchema::fulltext_definitions(document, &object_type.name).unwrap() {
1688	            pool.intern(defn.name.as_str());
1689	        }
1690	    }
1691	
1692	    pool
1693	}
