44	    static ref DEPLOYMENT: DeploymentHash = DeploymentHash::new("batchAppend").unwrap();
45	    static ref SCHEMA: InputSchema = InputSchema::parse_latest(GQL, DEPLOYMENT.clone()).unwrap();
46	    static ref THING_TYPE: EntityType = SCHEMA.entity_type("Thing").unwrap();
