+        assert!(!THING_TYPE.skip_duplicates(), "Thing (mutable) should not skip duplicates");
+
+        let mk_ins = |ty: &EntityType, block: BlockNumber| {
+            let key = ty.parse_key("one").unwrap();
+            EntityModification::Insert {
+                key,
+                data: Arc::new(entity! { schema => id: "one", count: block }),
+                block,
+                end: None,
+            }
+        };
+
+        // skip_duplicates: cross-block duplicate discarded, count stays 1
+        let mut g = RowGroup::new(dup_type.clone());
+        g.append_row(mk_ins(&dup_type, 1)).unwrap();
+        g.append_row(mk_ins(&dup_type, 2)).unwrap();
+        assert_eq!(1, g.row_count(), "cross-block dup should be discarded");
+
+        // skip_duplicates: same-block duplicate kept, count 2
+        let mut g = RowGroup::new(dup_type.clone());
+        g.append_row(mk_ins(&dup_type, 1)).unwrap();
+        g.append_row(mk_ins(&dup_type, 1)).unwrap();
+        assert_eq!(2, g.row_count(), "same-block dup should be kept");
+
+        // skip_duplicates: overwrite/remove are Ok and ignored
+        let mut g = RowGroup::new(dup_type.clone());
+        g.append_row(mk_ins(&dup_type, 1)).unwrap();
+        let ow = EntityModification::Overwrite {
+            key: dup_type.parse_key("one").unwrap(),
+            data: Arc::new(entity! { schema => id: "one", count: 5 }),
+            block: 2,
+            end: None,
+        };
+        assert!(g.append_row(ow).is_ok(), "overwrite should be Ok");
+        let rm = EntityModification::Remove { key: dup_type.parse_key("one").unwrap(), block: 3 };
+        assert!(g.append_row(rm).is_ok(), "remove should be Ok");
+        assert_eq!(1, g.row_count(), "overwrite/remove should be ignored");
+
+        // regular immutable: cross-block dup is an error
+        let mut g = RowGroup::new(imm_type.clone());
+        g.append_row(mk_ins(&imm_type, 1)).unwrap();
+        assert!(g.append_row(mk_ins(&imm_type, 2)).is_err(), "regular immutable cross-block dup must error");
+
+        // validation: skipDuplicates without immutable fails
+        const BAD: &str = r#"type Bad @entity(skipDuplicates: true) { id: ID! }"#;
+        let dep2 = DeploymentHash::new("badSkip").unwrap();
+        assert!(InputSchema::parse_latest(BAD, dep2).is_err(), "skipDuplicates without immutable must fail validation");
+    }
